#define PLANE_DISTANCE 0.5 + sin(iTime * 0.1) * 0.1
#define MAX_STEPS 200.0
#define COLLISION_DISTANCE 0.01
#define MAX_DISTANCE 100.0
#define FOG_DISTANCE 40.0
#define FOG_HARDNESS 3.0
#define DUNE_DISTANCE 30.0
#define PI 3.141592

struct TraceInfo {
    vec3 point;
    vec3 normal;
    bool isCollided;
};


vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}
vec2 fade(vec2 t) {return t*t*t*(t*(t*6.0-15.0)+10.0);}

// Shamesly stolen from here: https://gist.github.com/patriciogonzalezvivo/670c22f3966e662d2f83
float cnoise(vec2 P){
  vec4 Pi = floor(P.xyxy) + vec4(0.0, 0.0, 1.0, 1.0);
  vec4 Pf = fract(P.xyxy) - vec4(0.0, 0.0, 1.0, 1.0);
  Pi = mod(Pi, 289.0); // To avoid truncation effects in permutation
  vec4 ix = Pi.xzxz;
  vec4 iy = Pi.yyww;
  vec4 fx = Pf.xzxz;
  vec4 fy = Pf.yyww;
  vec4 i = permute(permute(ix) + iy);
  vec4 gx = 2.0 * fract(i * 0.0243902439) - 1.0; // 1/41 = 0.024...
  vec4 gy = abs(gx) - 0.5;
  vec4 tx = floor(gx + 0.5);
  gx = gx - tx;
  vec2 g00 = vec2(gx.x,gy.x);
  vec2 g10 = vec2(gx.y,gy.y);
  vec2 g01 = vec2(gx.z,gy.z);
  vec2 g11 = vec2(gx.w,gy.w);
  vec4 norm = 1.79284291400159 - 0.85373472095314 * 
    vec4(dot(g00, g00), dot(g01, g01), dot(g10, g10), dot(g11, g11));
  g00 *= norm.x;
  g01 *= norm.y;
  g10 *= norm.z;
  g11 *= norm.w;
  float n00 = dot(g00, vec2(fx.x, fy.x));
  float n10 = dot(g10, vec2(fx.y, fy.y));
  float n01 = dot(g01, vec2(fx.z, fy.z));
  float n11 = dot(g11, vec2(fx.w, fy.w));
  vec2 fade_xy = fade(Pf.xy);
  vec2 n_x = mix(vec2(n00, n01), vec2(n10, n11), fade_xy.x);
  float n_xy = mix(n_x.x, n_x.y, fade_xy.y);
  return 2.3 * n_xy;
}

float sphere(vec3 position, float radius) {
    position.x += sin(iTime * 10.0 + position.y * 10.0) * 0.03;
    position.z += sin(iTime * 13.123 + position.x * 13.23) * 0.02;
    position.y += sin(iTime * 2.123 + position.z * 6.23) * 0.01;
    return length(position) - radius;
}

float plane(vec3 position, vec3 normal, float height) {
    float noise = cnoise(position.xz * 0.13 + vec2(iTime * 0.5, 0.0));
    float percent = clamp(length(position.xz) / DUNE_DISTANCE, 0.0, 1.0);
    position.y += noise * 3.0 * pow(percent, 3.0);

    return dot(position, normal) + height;
}

float map(vec3 point) {
    return min(
        sphere(point - vec3(0.0, sin(iTime) * 0.1, 0.0), 1.0),
        plane(point, normalize(vec3(0.0, 1.0, 0.0)), 2.0)
    );
}

// Shamesly stolen from here: https://www.shadertoy.com/view/Xds3zN
vec3 getNormal(in vec3 pos) {
    vec3 n = vec3(0.0);
    for(int i = 0; i < 4; i++) {
        vec3 e = 0.5773 * (2.0 * vec3((((i + 3) >> 1) & 1),((i >> 1) & 1),(i & 1)) - 1.0);
        n += e * map(pos+0.01*e);
    }
    return normalize(n);
}

mat4 createTransform(vec3 position, vec3 forward, vec3 scale) {
    forward = normalize(forward);

    vec3 worldUp = abs(forward.y) > 0.999 ? vec3(1.0, 0.0, 0.0) : vec3(0.0, 1.0, 0.0);

    vec3 right = normalize(cross(worldUp, forward));
    vec3 up = cross(forward, right);

    return mat4(
        vec4(right * scale.x, 0.0),
        vec4(up * scale.y, 0.0),
        vec4(forward * scale.z, 0.0),
        vec4(position, 1.0)
    );
}

mat4 rotateAroundAxis(vec3 axis, float angle) {
    axis = normalize(axis);
    float c = cos(angle);
    float s = sin(angle);
    float one_c = 1.0 - c;

    // Rotation matrix components
    float xy = axis.x * axis.y * one_c;
    float xz = axis.x * axis.z * one_c;
    float yz = axis.y * axis.z * one_c;
    float xs = axis.x * s;
    float ys = axis.y * s;
    float zs = axis.z * s;

    return mat4(
        vec4(c + axis.x * axis.x * one_c, xy - zs, xz + ys, 0.0),
        vec4(xy + zs, c + axis.y * axis.y * one_c, yz - xs, 0.0),
        vec4(xz - ys, yz + xs, c + axis.z * axis.z * one_c, 0.0),
        vec4(0.0, 0.0, 0.0, 1.0)
    );
}

TraceInfo traceRay(mat4 transform, vec2 fragCoord) {
    float aspect = iResolution.x / iResolution.y;
    vec2 uv = fragCoord/iResolution.xy * 2.0 - 1.0;
    uv.y /= aspect;

    vec3 ray_origin = vec3(0.0);
    vec3 ray_direction = normalize(vec3(uv, PLANE_DISTANCE));
    mat4 ray_transform = createTransform(ray_origin, ray_direction, vec3(1.0));
    ray_transform = transform * ray_transform;

    ray_origin = ray_transform[3].xyz;
    ray_direction = ray_transform[2].xyz;

    TraceInfo trace;

    float dist = 10000.0;
    for (float i = 0.0; i < MAX_STEPS; i += 1.0) {
        dist = map(ray_origin);
        ray_origin += ray_direction * dist;

        if (dist < COLLISION_DISTANCE) {
            trace.point = ray_origin;
            trace.isCollided = true;
            trace.normal = getNormal(ray_origin);
            break;
        };
    }

    return trace;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    mat4 CameraTransform = createTransform(
        vec3(cos(iTime * 0.1), 0.5, sin(iTime * 0.1)) * 3.0,
        vec3(0.0, 0.0, 1.0),
        vec3(1.0, 1.0, 1.0)
    );

    CameraTransform *= rotateAroundAxis(vec3(0.0, 1.0, 0.0), iTime * 0.1 + 3.14 * 0.5)
        * rotateAroundAxis(vec3(1.0, 0.0, 0.0), PI * -0.15)
        * rotateAroundAxis(vec3(0.0, 0.0, 1.0), sin(iTime * 0.5) * 0.2)
        * rotateAroundAxis(vec3(1.0, 0.0, 0.0), cos(iTime * 0.8) * 0.2);

    CameraTransform[3].z += 1.0;

    TraceInfo d = traceRay(CameraTransform, fragCoord);

    vec4 fogColor = vec4(0.141, 0.306, 0.688, 1.0);

    if (d.isCollided) {
        // Base color
        vec4 materialColor = vec4(0.8, 0.2, 0.0, 1.0);
        fragColor = materialColor;

        // Sun
        vec3 sunDirection = normalize(vec3(1.0, -0.0, 0.0));
        vec4 sunColor = vec4(1.0, 1.0, 1.0, 1.0) * 2.0;
        float sunAffection = clamp(-dot(d.normal, sunDirection), 0.0, 1.0);
        sunAffection = pow(sunAffection, 1.0 / 10.0);
        fragColor *= sunColor;

        // Sky reflection
        float ambientAffection = clamp(dot(vec3(0.0, 1.0, 0.0), d.normal), 0.0, 1.0);
        fragColor += fogColor * ambientAffection;
        fragColor /= 2.0;

        // Ambient color
        fragColor = mix(fragColor, fogColor * 0.2, 1.0 - sunAffection);

        // Fog        
        float dist = clamp(1.0 - length(d.point - CameraTransform[3].xyz) / FOG_DISTANCE, 0.0, 1.0);
        dist = pow(dist, 1.0 / FOG_HARDNESS);

        fragColor = mix(fragColor, fogColor, 1.0 - dist);
    } else {
        fragColor = fogColor;
    }
}
